updates={'experiments/barcelona/empaquetar_examen.py': '"""Empaqueta examen autorizado sin modificar arrays: base + parches exactos."""\nimport hashlib\nimport json\nfrom pathlib import Path\nimport shutil\nimport tarfile\n\nimport numpy as np\nimport pandas as pd\n\nROOT=Path(__file__).resolve().parents[2]\n\n\ndef sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()\n\n\ndef indices_iguales(a,b):\n    """Compara instantes UTC, tolerando sólo representación us/ns, no desfases."""\n    if a.tz is None or b.tz is None:return False\n    return a.tz_convert(\'UTC\').as_unit(\'ns\').equals(b.tz_convert(\'UTC\').as_unit(\'ns\'))\n\n\ndef firma(a):\n    a=np.ascontiguousarray(a)\n    return dict(shape=list(a.shape),dtype=str(a.dtype),sha256=hashlib.sha256(a.tobytes()).hexdigest())\n\n\ndef parche(a,b):\n    a,b=np.ascontiguousarray(a),np.ascontiguousarray(b)\n    assert a.shape==b.shape and a.dtype==b.dtype\n    tipo=np.dtype(\'u\'+str(a.dtype.itemsize))\n    pos=np.flatnonzero(a.view(tipo).ravel()!=b.view(tipo).ravel()).astype(\'int32\')\n    val=a.ravel()[pos].copy()\n    c=b.copy();c.ravel()[pos]=val\n    assert firma(c)==firma(a)\n    return pos,val\n\n\ndef main():\n    base=ROOT/\'results/barcelona_paraad\';out=base/\'examen_colab_2018_2019\'\n    stage=out/\'paquete\';ent=stage/\'entrada\';ent.mkdir(parents=True,exist_ok=False)\n    w=base/\'ventanas_v1\';a=base/\'ataques_proporcionales_v1\';cal=base/\'calibracion_2017_colab\'\n    assert json.loads((cal/\'verificacion_final.json\').read_text())[\'igual\']\n    globalv=pd.read_parquet(w/\'valores.parquet\')\n    globalb=pd.read_parquet(w/\'perfiles_causales.parquet\')\n    clock=pd.read_parquet(w/\'reloj.parquet\');dias=pd.read_parquet(w/\'estacion_dias.parquet\')\n    ml=pd.read_parquet(w/\'horas_validas_l0.parquet\');mv=pd.read_parquet(w/\'horas_validas_v4.parquet\')\n    z=np.load(w/\'z_definitivo.npy\',mmap_mode=\'r\');F=np.load(w/\'l0_features_definitivo.npy\',mmap_mode=\'r\')\n    info={};bases={}\n    for ano in [2017,2018,2019]:\n        start=pd.Timestamp(f\'{ano}-01-01\',tz=\'UTC\');end=pd.Timestamp(f\'{ano+1}-01-01\',tz=\'UTC\')\n        p0=max(0,int(globalv.index.searchsorted(start))-24);p1=int(globalv.index.searchsorted(end))\n        sl=slice(p0,p1);idx=globalv.index[sl]\n        arrays=dict(v=globalv.iloc[sl].to_numpy(\'float64\'),b=globalb.iloc[sl].to_numpy(\'float64\'),\n                    z=np.asarray(z[sl]),F=np.asarray(F[sl]),\n                    valid_l0=ml.iloc[sl].to_numpy(bool),valid_v4=mv.iloc[sl].to_numpy(bool),\n                    hora=clock[[\'hora_sin\',\'hora_cos\']].iloc[sl].to_numpy(\'float32\'))\n        arrays={n:np.ascontiguousarray(x) for n,x in arrays.items()}\n        np.savez_compressed(ent/f\'base_{ano}.npz\',**arrays)\n        pd.DataFrame(index=idx).to_parquet(ent/f\'indice_{ano}.parquet\')\n        sd=dias[dias.dia_utc.dt.year==ano].copy();sd[\'inicio_pos\']-=p0;sd[\'fin_pos\']-=p0\n        sd.to_parquet(ent/f\'dias_{ano}.parquet\',index=False)\n        info[str(ano)]=dict(offset=p0,arrays={n:firma(x) for n,x in arrays.items()},casos=int(sd.comun.sum()))\n        bases[ano]=(arrays,idx,sd)\n    unidades=[]\n    for carpeta in sorted(a.glob(\'*201[89]_[0-9][0-9]\')):\n        ano=2018 if carpeta.name.startswith(\'prueba\') else 2019\n        ref,idx,sd=bases[ano]\n        for delta in [100,50,20,10,5]:\n            p=carpeta/f\'d{delta}\'\n            original=json.loads((p/\'completo.json\').read_text())\n            for n,h in original[\'sha256_salidas\'].items():assert sha(p/n)==h\n            v=pd.read_parquet(p/\'valores_alterados.parquet\');assert v.index.equals(idx)\n            arrays=dict(v=v.to_numpy(\'float64\'),b=pd.read_parquet(p/\'perfiles_causales.parquet\').to_numpy(\'float64\'),\n                        z=np.load(p/\'z.npy\'),F=np.load(p/\'l0_features.npy\'))\n            patch={};firmas={}\n            for n,x in arrays.items():\n                patch[n+\'_i\'],patch[n+\'_x\']=parche(x,ref[n]);firmas[n]=firma(x)\n            nombre=f\'{carpeta.name}_d{delta}\'\n            np.savez_compressed(ent/f\'{nombre}.npz\',**patch)\n            labels=pd.read_parquet(p/\'estacion_dias.parquet\')\n            label=labels.pivot(index=\'dia_utc\',columns=\'estacion\',values=\'etiqueta\').reindex(columns=globalv.columns).to_numpy(bool)\n            labels2=sd.pivot(index=\'dia_utc\',columns=\'estacion\',values=\'comun\').reindex(columns=globalv.columns)\n            assert int(labels2.to_numpy().sum())==info[str(ano)][\'casos\']\n            np.save(ent/f\'{nombre}_y.npy\',label,allow_pickle=False)\n            unidades.append(dict(nombre=nombre,ano=ano,plan=carpeta.name,delta=delta,arrays=firmas))\n    assert len(unidades)==100\n    (ent/\'unidades.json\').write_text(json.dumps(unidades,indent=2)+\'\\n\')\n    (ent/\'bases.json\').write_text(json.dumps(info,indent=2)+\'\\n\')\n    (ent/\'codigos.json\').write_text(json.dumps(list(globalv.columns))+\'\\n\')\n    shutil.copyfile(w/\'vecinas.json\',ent/\'vecinas.json\')\n    modeldir=ent/\'modelos\';modeldir.mkdir()\n    train=base/\'colab_20261029\'\n    tabla=pd.read_csv(train/\'seleccion_modelos_verificada.csv\',dtype={\'estacion\':str})\n    for row in tabla.itertuples():\n        r=train/row.detector/\'recuperado/salidas\'/row.detector\n        r=(r/row.estacion if row.detector==\'v4\' else r)/\'definitivo/r1/modelo.keras\'\n        assert sha(r)==row.sha256_modelo\n        shutil.copyfile(r,modeldir/(f\'v4_{row.estacion}.keras\' if row.detector==\'v4\' else f\'{row.detector}.keras\'))\n    c=cal/\'recuperado/salidas/calibracion\'\n    for n in [\'congelado.json\',\'p95_v4.csv\']+[\'puntajes_\'+d+\'.csv\' for d in [\'l0\',\'v4\',\'paraad\']]:\n        shutil.copyfile(c/n,ent/(\'calibracion_\'+n))\n    for p in (cal/\'paquete\').rglob(\'*.py\'):\n        rel=p.relative_to(cal/\'paquete\');dst=stage/rel;dst.parent.mkdir(parents=True,exist_ok=True)\n        shutil.copyfile(ROOT/rel if (ROOT/rel).exists() else p,dst)\n    for n in [\'empaquetar_examen.py\',\'evaluar_examen_colab.py\']:\n        shutil.copyfile(ROOT/\'experiments/barcelona\'/n,stage/\'experiments/barcelona\'/n)\n    shutil.copyfile(cal/\'paquete/requirements.txt\',stage/\'requirements.txt\')\n    shutil.copyfile(ROOT/\'docs/registro_examen_barcelona_2018_2019.md\',ent/\'registro_previo.md\')\n    meta=dict(alcance=\'Examen autorizado2018–2019 y control limpio2017, sin entrenamiento\',\n               archivos={str(p.relative_to(stage)):sha(p) for p in sorted(stage.rglob(\'*\')) if p.is_file()})\n    (ent/\'registro_paquete.json\').write_text(json.dumps(meta,ensure_ascii=False,indent=2)+\'\\n\')\n    paquete=out/\'examen_barcelona.tar.gz\'\n    with tarfile.open(paquete,\'w:gz\') as tar:\n        for p in sorted(stage.rglob(\'*\')):\n            if p.is_file():tar.add(p,arcname=str(p.relative_to(stage)),recursive=False)\n    partes=[]\n    with paquete.open(\'rb\') as f:\n        i=0\n        while b:=f.read(8*1024*1024):\n            n=f\'examen_parte_{i:03}.bin\';(out/n).write_bytes(b)\n            partes.append(dict(nombre=n,sha256=hashlib.sha256(b).hexdigest()));i+=1\n    (out/\'transferencia.json\').write_text(json.dumps(dict(bytes=paquete.stat().st_size,sha256=sha(paquete),partes=partes,matrices=102),indent=2)+\'\\n\')\n    print((out/\'transferencia.json\').read_text())\n\n\nif __name__==\'__main__\':main()\n', 'experiments/barcelona/evaluar_examen_colab.py': '"""Examen congelado CPU; produce puntajes duplicados, no selecciona modelos."""\nimport os\nfor k,v in {\'CUDA_VISIBLE_DEVICES\':\'-1\',\'TF_ENABLE_ONEDNN_OPTS\':\'0\',\'TF_DETERMINISTIC_OPS\':\'1\',\n            \'TF_NUM_INTRAOP_THREADS\':\'1\',\'TF_NUM_INTEROP_THREADS\':\'1\',\'OMP_NUM_THREADS\':\'1\'}.items():os.environ[k]=v\nimport argparse\nimport hashlib\nimport json\nfrom pathlib import Path\nimport platform\n\nimport numpy as np\nimport pandas as pd\nimport tensorflow as tf\n\nfrom experiments.barcelona.calibrar_2017_colab import cargar,predecir\nfrom experiments.barcelona.empaquetar_examen import firma,indices_iguales\nfrom experiments.barcelona.preparar_ventanas import ventana_l0,ventana_v4,bloque_paraad\n\nROOT=Path(__file__).resolve().parents[2]\n\n\ndef sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()\n\n\ndef guardar(p,x):\n    p.parent.mkdir(parents=True,exist_ok=True);tmp=p.with_suffix(\'.tmp\')\n    tmp.write_text(json.dumps(x,ensure_ascii=False,indent=2,allow_nan=False)+\'\\n\');tmp.replace(p)\n\n\ndef leer_base(d,ano,codes):\n    arrays={n:x for n,x in np.load(d/f\'base_{ano}.npz\').items()}\n    meta=json.loads((d/\'bases.json\').read_text())[str(ano)]\n    for n,x in arrays.items():assert firma(x)==meta[\'arrays\'][n]\n    idx=pd.read_parquet(d/f\'indice_{ano}.parquet\').index\n    sd=pd.read_parquet(d/f\'dias_{ano}.parquet\')\n    comun=sd.pivot(index=\'dia_utc\',columns=\'estacion\',values=\'comun\').reindex(columns=codes)\n    assert int(comun.to_numpy().sum())==meta[\'casos\']\n    return arrays,idx,sd,comun\n\n\ndef reconstruir(d,u,base):\n    patch=np.load(d/(u[\'nombre\']+\'.npz\'))\n    arrays=dict(base)\n    for n,meta in u[\'arrays\'].items():\n        x=base[n].copy();x.ravel()[patch[n+\'_i\']]=patch[n+\'_x\']\n        assert firma(x)==meta,(u[\'nombre\'],n)\n        arrays[n]=x\n    assert np.array_equal(np.isnan(arrays[\'v\']),np.isnan(base[\'v\']))\n    return arrays\n\n\ndef inferir(detector,modelos,a,idx,sd,comun,codes,vec,p95):\n    ano=int(comun.index[0].year);cal=idx.year==ano\n    if detector==\'l0\':\n        h=pd.DataFrame(np.nan,index=idx[cal],columns=codes)\n        for j,s in enumerate(codes):\n            pos=np.flatnonzero(a[\'valid_l0\'][:,j] & cal)\n            X=ventana_l0(a[\'F\'],codes,vec,s,pos)\n            val=predecir(modelos[\'l0\'],X).ravel().astype(\'float64\');assert np.isfinite(val).all()\n            h.loc[idx[pos],s]=val\n        score=h.groupby(h.index.normalize()).mean().where(h.notna().groupby(h.index.normalize()).sum()>=12)\n    elif detector==\'v4\':\n        h=pd.DataFrame(np.nan,index=idx[cal],columns=codes)\n        for j,s in enumerate(codes):\n            pos=np.flatnonzero(a[\'valid_v4\'][:,j] & cal)\n            X=ventana_v4(a[\'z\'],np.isfinite(a[\'v\']).astype(\'float32\'),a[\'hora\'],j,pos)\n            cor=predecir(modelos[s],X).ravel().astype(\'float64\')\n            val=a[\'v\'][pos,j]-a[\'b\'][pos,j]-cor;assert np.isfinite(val).all()\n            h.loc[idx[pos],s]=val\n        score=(h.groupby(h.index.normalize()).mean().abs()/p95).where(h.notna().groupby(h.index.normalize()).sum()>=12)\n    else:\n        pos=sd[sd.bloque_seguro].inicio_pos.drop_duplicates().to_numpy()\n        X,m=bloque_paraad(a[\'z\'],np.isfinite(a[\'v\']).astype(\'float32\'),pos)\n        rec=predecir(modelos[\'paraad\'],X)\n        n=m.sum(axis=2);err=(np.abs(X.astype(\'float64\')-rec)*m).sum(axis=2)\n        val=np.divide(err,n,out=np.full(err.shape,np.nan),where=n>=12)\n        score=pd.DataFrame(val,index=idx[pos].normalize(),columns=codes)\n    score=score.reindex(index=comun.index,columns=codes).where(comun)\n    assert np.isfinite(score.to_numpy()[comun.to_numpy()]).all()\n    return score\n\n\ndef unidad(out,nombre,detector,modelos,a,idx,sd,comun,codes,vec,p95,meta=None):\n    carpeta=out/nombre;listo=carpeta/\'completo.json\'\n    if listo.exists():\n        r=json.loads(listo.read_text())\n        for n,h in r[\'sha256\'].items():assert sha(carpeta/n)==h\n        return np.load(carpeta/\'puntajes.npy\')\n    previo=None\n    for r in (1,2):\n        guardar(out/\'progreso.json\',dict(unidad=nombre,repeticion=r,detector=detector))\n        s=inferir(detector,modelos,a,idx,sd,comun,codes,vec,p95)\n        if previo is not None:pd.testing.assert_frame_equal(previo,s,check_exact=True)\n        previo=s\n    carpeta.mkdir(exist_ok=True);np.save(carpeta/\'puntajes.npy\',s.to_numpy(),allow_pickle=False)\n    guardar(carpeta/\'datos.json\',dict(nombre=nombre,detector=detector,ano=int(comun.index[0].year),\n                                     casos=int(comun.to_numpy().sum()),igual=True,unidad=meta))\n    guardar(listo,dict(sha256={n:sha(carpeta/n) for n in [\'puntajes.npy\',\'datos.json\']}))\n    print(\'COMPLETO\',detector,nombre,flush=True)\n    return s.to_numpy()\n\n\ndef main():\n    ap=argparse.ArgumentParser();ap.add_argument(\'--detector\',choices=[\'l0\',\'v4\',\'paraad\'],required=True);args=ap.parse_args()\n    d=ROOT/\'entrada\';out=ROOT/\'salidas\'/args.detector\n    assert not tf.config.get_visible_devices(\'GPU\')\n    assert tf.__version__==\'2.21.0\' and tf.keras.__version__==\'3.13.2\'\n    paquete=json.loads((d/\'registro_paquete.json\').read_text())\n    for n,h in paquete[\'archivos\'].items():assert sha(ROOT/n)==h,n\n    calib=json.loads((d/\'calibracion_congelado.json\').read_text())\n    for n,h in calib[\'modelos\'].items():assert sha(d/\'modelos\'/n)==h\n    assert sha(d/\'calibracion_p95_v4.csv\')==calib[\'sha256_p95_v4\']\n    codes=json.loads((d/\'codigos.json\').read_text());vec=json.loads((d/\'vecinas.json\').read_text())\n    p95=pd.read_csv(d/\'calibracion_p95_v4.csv\',dtype={\'estacion\':str},float_precision=\'round_trip\').set_index(\'estacion\').iloc[:,0]\n    firma_entrada=dict(sha256_paquete=sha(d/\'registro_paquete.json\'),sha256_script=sha(Path(__file__)),\n                       sha256_calibracion=sha(d/\'calibracion_congelado.json\'),tensorflow=tf.__version__,keras=tf.keras.__version__,\n                       numpy=np.__version__,python=platform.python_version(),detector=args.detector,\n                       origen=\'Modelos congelados cargados; sin entrenamiento\')\n    if (out/\'entrada.json\').exists():assert json.loads((out/\'entrada.json\').read_text())==firma_entrada\n    else:guardar(out/\'entrada.json\',firma_entrada)\n    modelos={s:cargar(d/f\'modelos/v4_{s}.keras\') for s in codes} if args.detector==\'v4\' else {\n        args.detector:cargar(d/f\'modelos/{args.detector}.keras\')}\n    arrays,idx,sd,comun=leer_base(d,2017,codes)\n    s=unidad(out,\'control_2017\',args.detector,modelos,arrays,idx,sd,comun,codes,vec,p95)\n    ref=pd.read_csv(d/f\'calibracion_puntajes_{args.detector}.csv\',index_col=\'dia_utc\',parse_dates=[\'dia_utc\'],float_precision=\'round_trip\')\n    assert indices_iguales(ref.index,comun.index) and ref.columns.equals(comun.columns)\n    m=comun.to_numpy();np.testing.assert_allclose(s[m],ref.to_numpy()[m],rtol=1e-6,atol=1e-6)\n    cambios={p:int(((s[m]>u)!=(ref.to_numpy()[m]>u)).sum()) for p,u in calib[\'umbrales\'][args.detector].items()}\n    guardar(out/\'control_calibracion.json\',dict(tolerancia_rtol=1e-6,tolerancia_atol=1e-6,\n            maxima_diferencia=float(np.abs(s[m]-ref.to_numpy()[m]).max()),cambios_alertas=cambios,\n            nota=\'No se ajustan los umbrales por diferencias entre VMs\'))\n    unidades=json.loads((d/\'unidades.json\').read_text())\n    for ano in [2018,2019]:\n        base,idx,sd,comun=leer_base(d,ano,codes)\n        unidad(out,f\'limpio_{ano}\',args.detector,modelos,base,idx,sd,comun,codes,vec,p95)\n        for u in [x for x in unidades if x[\'ano\']==ano]:\n            a=reconstruir(d,u,base)\n            unidad(out,u[\'nombre\'],args.detector,modelos,a,idx,sd,comun,codes,vec,p95,meta=u)\n    listos=sorted(out.glob(\'*/completo.json\'));assert len(listos)==103\n    guardar(out/\'congelado.json\',dict(igual=True,unidades_examen=102,control2017=True,entrada=firma_entrada,\n                 sha256_unidades={str(p.relative_to(out)):sha(p) for p in listos}))\n\n\nif __name__==\'__main__\':main()\n'}
